export type NB={bounds?:RangeBounds.<any>};
meta NB {
 default={};
 validate(value,c){return c.bounds===undefined || c.bounds.contains(value);}
 subtype(a,b){if(b.bounds===undefined)return true;if(a.bounds===undefined)return false;return b.bounds.contains(a.bounds);}
 meet(a,b){if(a.bounds===undefined)return b;if(b.bounds===undefined)return a;const r=a.bounds.intersect(b.bounds);return r.isEmpty?null:{bounds:r};}
